CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(30) NOT NULL UNIQUE, email VARCHAR(255) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, role ENUM('student','teacher','registrar','admin') NOT NULL DEFAULT 'student', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS students (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL UNIQUE, lrn VARCHAR(20), psa_birth_cert_no VARCHAR(50), extension_name VARCHAR(30), first_name VARCHAR(100), middle_name VARCHAR(100), last_name VARCHAR(100), birth_date DATE, gender VARCHAR(30), place_of_birth VARCHAR(255), nationality VARCHAR(80), religion VARCHAR(100), mother_tongue VARCHAR(100), contact_number VARCHAR(50), is_4ps TINYINT(1) DEFAULT 0, fourps_household_id VARCHAR(50), is_ip TINYINT(1) DEFAULT 0, ip_community VARCHAR(150), is_pwd TINYINT(1) DEFAULT 0, pwd_type VARCHAR(150), cur_house_no VARCHAR(50), cur_street VARCHAR(150), cur_barangay VARCHAR(150), cur_municipality VARCHAR(150), cur_province VARCHAR(150), cur_country VARCHAR(80) DEFAULT 'Philippines', cur_zip VARCHAR(10), perm_same_as_current TINYINT(1) DEFAULT 1, perm_house_no VARCHAR(50), perm_street VARCHAR(150), perm_barangay VARCHAR(150), perm_municipality VARCHAR(150), perm_province VARCHAR(150), perm_country VARCHAR(80) DEFAULT 'Philippines', perm_zip VARCHAR(10), address TEXT, father_last VARCHAR(100), father_first VARCHAR(100), father_middle VARCHAR(100), father_contact VARCHAR(50), mother_last VARCHAR(100), mother_first VARCHAR(100), mother_middle VARCHAR(100), mother_contact VARCHAR(50), guardian_last VARCHAR(100), guardian_first VARCHAR(100), guardian_middle VARCHAR(100), guardian_contact VARCHAR(50), guardian_relationship VARCHAR(80), sne_program TINYINT(1) DEFAULT 0, sne_diagnosis VARCHAR(255), sne_manifestations JSON, has_pwd_id TINYINT(1) DEFAULT 0, last_grade_completed VARCHAR(30), last_sy_completed VARCHAR(20), last_school_attended VARCHAR(255), last_school_id VARCHAR(50), learner_type VARCHAR(80), previous_school VARCHAR(255), jhs_graduated VARCHAR(255), grade_level VARCHAR(10), semester VARCHAR(30), dl_modalities JSON, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS rate_limits (limit_key VARCHAR(191) PRIMARY KEY, points INT NOT NULL, reset_at DATETIME NOT NULL, INDEX(reset_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS enrollments (id INT AUTO_INCREMENT PRIMARY KEY, student_id INT NOT NULL, school_year VARCHAR(20) NOT NULL, grade_level VARCHAR(10) NOT NULL, semester VARCHAR(30), preferred_track VARCHAR(100), curriculum_exit VARCHAR(100), recommended_strand VARCHAR(20), chosen_strand VARCHAR(20), admin_strand_override VARCHAR(20), admin_override_reason TEXT, remarks TEXT, status ENUM('Pending','Confirmed','Incomplete','Rejected') DEFAULT 'Pending', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS riasec_results (id INT AUTO_INCREMENT PRIMARY KEY, enrollment_id INT NOT NULL UNIQUE, score_r INT NOT NULL, score_i INT NOT NULL, score_a INT NOT NULL, score_s INT NOT NULL, score_e INT NOT NULL, score_c INT NOT NULL, answers JSON NOT NULL, computed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(enrollment_id) REFERENCES enrollments(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS student_electives (id INT AUTO_INCREMENT PRIMARY KEY, enrollment_id INT NOT NULL, elective_key VARCHAR(100) NOT NULL, elective_rank INT NOT NULL, UNIQUE KEY enrollment_elective(enrollment_id,elective_key), FOREIGN KEY(enrollment_id) REFERENCES enrollments(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS plan_of_study (id INT AUTO_INCREMENT PRIMARY KEY, enrollment_id INT NOT NULL, elective_key VARCHAR(100) NOT NULL, elective_name VARCHAR(255) NOT NULL, elective_rank INT NOT NULL, hours INT NOT NULL, track_type VARCHAR(100), cluster VARCHAR(100), FOREIGN KEY(enrollment_id) REFERENCES enrollments(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS requirements (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL, description TEXT, is_required TINYINT(1) DEFAULT 1, is_active TINYINT(1) DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS student_documents (id INT AUTO_INCREMENT PRIMARY KEY, student_id INT NOT NULL, requirement_id INT NOT NULL, file_path VARCHAR(255) NOT NULL, original_name VARCHAR(255), mime_type VARCHAR(100), status ENUM('Submitted','Verified','Rejected') DEFAULT 'Submitted', admin_note TEXT, verified_at DATETIME NULL, verified_by INT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE, FOREIGN KEY(requirement_id) REFERENCES requirements(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS notifications (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, title VARCHAR(150) NOT NULL, message TEXT NOT NULL, is_read TINYINT(1) DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS audit_logs (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NULL, action VARCHAR(100) NOT NULL, entity_type VARCHAR(80), entity_id INT NULL, details JSON, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS password_resets (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, expires_at DATETIME NOT NULL, used_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(token_hash), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS app_sessions (sid VARCHAR(128) PRIMARY KEY, data JSON NOT NULL, expires_at DATETIME NOT NULL, INDEX(expires_at)) ENGINE=InnoDB;
